<tr data-kendala-id="{{ $k->id }}" data-search="{{ strtolower(($k->satuan->nama ?? '').' '.$k->perihal) }}" data-prioritas="{{ $k->prioritas }}"><td><div class="sender">{{ $k->satuan->nama ?? '-' }}</div></td><td><div class="subject">{{ $k->perihal }}</div></td><td>{{ $k->prioritas }}</td><td><span class="status-pill {{ in_array($k->status, ['Ditindaklanjuti','Selesai'], true) ? 'ok' : ($k->status === 'Ditolak' ? 'bad' : 'wait') }}">{{ $k->status }}</span></td><td>{{ $k->created_at->translatedFormat('d M Y H:i') }}</td><td><div class="action-row"><button type="button" class="detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($k->satuan->nama ?? '-') }}" data-tujuan="{{ e($satuan->nama) }}" data-perihal="{{ e($k->perihal) }}" data-prioritas="{{ e($k->prioritas) }}" data-proyek="{{ e($k->kategori ?? '-') }}" data-tanggal="{{ e($k->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($k->deskripsi) }}" data-kendala="{{ e($k->catatan ?? '') }}" data-lampiran="{{ $k->lampiran_path ? e(collect([['url' => asset('storage/'.$k->lampiran_path), 'nama' => basename($k->lampiran_path)]])->toJson()) : '[]' }}" @php $kendalaAdaAksi = in_array($k->status, ['Menunggu','Ditindaklanjuti'], true) || strtoupper($satuan->kode ?? '') === 'DANPUS'; @endphp data-readonly="{{ $kendalaAdaAksi ? '0' : '1' }}"@if(! $kendalaAdaAksi) data-readonly-text="Kendala ini sudah ditindaklanjuti — status: {{ $k->status }}."@endif>Detail</button>@if($k->status === 'Menunggu' && strtoupper($satuan->kode ?? '') !== 'DANPUS')<form method="POST" action="{{ route('laporan-kendala.status', $k) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Ditindaklanjuti"><button class="approve" type="submit">Tindak Lanjuti</button></form><form method="POST" action="{{ route('laporan-kendala.status', $k) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Ditolak"><button class="reject" type="submit">Tolak</button></form>@elseif($k->status === 'Ditindaklanjuti')<